const pptxgen = require("pptxgenjs");

// Color palette: Midnight Executive with data-forward accent
const C = {
  navy: "1E2761",
  ice: "CADCFC",
  white: "FFFFFF",
  slate: "334155",
  lightSlate: "64748B",
  accent: "0EA5E9", // bright data blue
  accent2: "8B5CF6", // purple for variety
  accent3: "10B981", // emerald for growth
  accent4: "F59E0B", // amber for caution
  bgLight: "F8FAFC",
  cardBg: "FFFFFF",
  grid: "E2E8F0"
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "The 2025 LLM Usage Landscape: Real-World Data from OpenRouter";
pres.author = "Data Analysis Team";
pres.subject = "LLM Market Analysis";

// Helper: fresh shadow factory
const makeShadow = (opacity = 0.12) => ({
  type: "outer",
  blur: 6,
  offset: 2,
  angle: 135,
  color: "000000",
  opacity
});

// ===== SLIDE 1: Title =====
{
  const s = pres.addSlide();
  s.background = { color: C.navy };
  // Decorative accent shape
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 5.625,
    fill: { color: C.navy }
  });
  // Subtle top accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }
  });
  // Title
  s.addText("The 2025 LLM Usage Landscape", {
    x: 0.6, y: 1.6, w: 8.8, h: 1.0,
    fontSize: 40, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", valign: "middle"
  });
  // Subtitle
  s.addText("Real-World Data from OpenRouter", {
    x: 0.6, y: 2.55, w: 8.8, h: 0.5,
    fontSize: 22, fontFace: "Calibri",
    color: C.ice, align: "left", valign: "middle"
  });
  // Source line
  s.addText("OpenRouter Rankings | Latest week of March 2025", {
    x: 0.6, y: 3.2, w: 8.8, h: 0.35,
    fontSize: 14, fontFace: "Calibri Light",
    color: C.ice, align: "left", valign: "middle"
  });
  // Headline metric callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.9, w: 3.2, h: 1.0,
    fill: { color: C.accent, transparency: 15 },
    rectRadius: 0.08
  });
  s.addText("26T+", {
    x: 0.6, y: 3.95, w: 3.2, h: 0.55,
    fontSize: 36, fontFace: "Calibri", bold: true,
    color: C.accent, align: "center", valign: "middle"
  });
  s.addText("Tokens processed this week", {
    x: 0.6, y: 4.45, w: 3.2, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: C.ice, align: "center", valign: "middle"
  });
}

// ===== SLIDE 2: Top 10 Models (Table) =====
{
  const s = pres.addSlide();
  s.background = { color: C.bgLight };
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }
  });
  s.addText("This Week's Top 10 Models", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Calibri", bold: true,
    color: C.navy, align: "left", valign: "middle"
  });

  const rows = [
    [
      { text: "Rank", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "Model", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "left" } },
      { text: "Provider", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "left" } },
      { text: "Weekly Tokens", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "WoW Change", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } }
    ],
    ["1", "MiMo-V2-Pro", "Xiaomi", "3.96T", "+165%"],
    ["2", "Step 3.5 Flash (free)", "Stepfun", "1.49T", "+1%"],
    ["3", "MiniMax M2.7", "MiniMax", "1.29T", "+253%"],
    ["4", "DeepSeek V3.2", "DeepSeek", "1.24T", "+9%"],
    ["5", "Claude Sonnet 4.6", "Anthropic", "1.04T", "-0%"],
    ["6", "Claude Opus 4.6", "Anthropic", "995B", "+2%"],
    ["7", "Gemini 3 Flash Preview", "Google", "972B", "+3%"],
    ["8", "GLM 5 Turbo", "Zhipu (z-ai)", "968B", "-6%"],
    ["9", "MiniMax M2.5", "MiniMax", "909B", "-30%"],
    ["10", "Grok 4.1 Fast", "x-ai", "599B", "+32%"]
  ];

  // Color coding for growth
  const growthColors = [C.accent3, C.lightSlate, C.accent3, C.accent3, C.lightSlate, C.lightSlate, C.lightSlate, C.lightSlate, C.accent4, C.accent3];

  const tableData = rows.map((row, ri) => {
    if (ri === 0) return row;
    return row.map((cell, ci) => {
      const base = { align: ci === 0 || ci >= 3 ? "center" : "left", fontSize: 12, fontFace: "Calibri", color: C.slate };
      if (ci === 4) {
        const isPositive = String(cell).startsWith("+");
        const isNegative = String(cell).startsWith("-");
        const col = isPositive ? C.accent3 : (isNegative && cell !== "-0%" ? C.accent4 : C.lightSlate);
        return { text: cell, options: { ...base, color: col, bold: true } };
      }
      if (ri === 1 && ci === 1) {
        return { text: cell, options: { ...base, bold: true, color: C.navy } };
      }
      return { text: cell, options: base };
    });
  });

  s.addTable(tableData, {
    x: 0.5, y: 1.0, w: 9, h: 4.2,
    colW: [0.8, 3.2, 2.0, 1.5, 1.5],
    border: { pt: 0.5, color: C.grid },
    fill: { color: C.cardBg },
    fontFace: "Calibri",
    fontSize: 12,
    color: C.slate,
    valign: "middle"
  });

  // Key insight callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fill: { color: C.navy }
  });
  s.addText("Chinese providers hold 6 of the top 10 spots. Xiaomi's MiMo-V2-Pro leads at 3.96T tokens (+165%).", {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fontSize: 12, fontFace: "Calibri",
    color: C.white, align: "center", valign: "middle"
  });
}

// ===== SLIDE 3: Provider Market Share (Pie Chart) =====
{
  const s = pres.addSlide();
  s.background = { color: C.bgLight };
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }
  });
  s.addText("Provider Market Share Breakdown", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Calibri", bold: true,
    color: C.navy, align: "left", valign: "middle"
  });

  s.addChart(pres.charts.PIE, [{
    name: "Market Share",
    labels: ["Xiaomi", "Google", "Anthropic", "MiniMax", "OpenAI", "Stepfun", "DeepSeek", "Zhipu", "x-ai", "Others"],
    values: [25.9, 11.8, 11.0, 8.5, 7.9, 6.8, 6.6, 6.5, 3.9, 11.2]
  }], {
    x: 0.3, y: 1.0, w: 5.5, h: 4.2,
    showPercent: true,
    showLegend: true,
    legendPos: "r",
    legendFontSize: 11,
    legendColor: C.slate,
    chartColors: [C.accent, C.accent2, "F59E0B", C.accent3, "EF4444", "EC4899", "06B6D4", "84CC16", "F97316", "94A3B8"],
    chartArea: { fill: { color: C.bgLight }, roundedCorners: true },
    dataLabelColor: C.white,
    dataLabelFontSize: 10,
    dataLabelPosition: "bestFit"
  });

  // Right-side insights
  const insights = [
    { label: "Xiaomi", value: "25.9%", desc: "More than double 2nd place" },
    { label: "Chinese Providers", value: "54.3%", desc: "Combined share exceeds half the market" },
    { label: "OpenAI", value: "7.9%", desc: "Ranks only 5th in real-world usage" },
    { label: "Fragmentation", value: "Top 10", desc: "8 different providers — no monopoly" }
  ];

  insights.forEach((ins, i) => {
    const y = 1.1 + i * 1.05;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.2, y: y, w: 3.5, h: 0.9,
      fill: { color: C.cardBg },
      shadow: makeShadow(0.1)
    });
    s.addText(ins.value, {
      x: 6.35, y: y + 0.1, w: 1.0, h: 0.4,
      fontSize: 20, fontFace: "Calibri", bold: true,
      color: C.accent, align: "left", valign: "middle"
    });
    s.addText(ins.label, {
      x: 7.4, y: y + 0.1, w: 2.2, h: 0.4,
      fontSize: 14, fontFace: "Calibri", bold: true,
      color: C.navy, align: "left", valign: "middle"
    });
    s.addText(ins.desc, {
      x: 6.35, y: y + 0.48, w: 3.2, h: 0.3,
      fontSize: 11, fontFace: "Calibri Light",
      color: C.lightSlate, align: "left", valign: "middle"
    });
  });
}

// ===== SLIDE 4: Shifts in the Market Landscape =====
{
  const s = pres.addSlide();
  s.background = { color: C.bgLight };
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }
  });
  s.addText("Shifts in the Market Landscape", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Calibri", bold: true,
    color: C.navy, align: "left", valign: "middle"
  });

  // Three trend cards
  const trends = [
    {
      title: "Chinese Models Break Through",
      body: "On this international platform, Chinese providers now account for over 54% of all usage. Xiaomi, DeepSeek, and MiniMax hold a significant cost-performance advantage.",
      color: C.accent
    },
    {
      title: "Flash/Turbo Variants Outpace Flagships",
      body: "Step 3.5 Flash, GLM 5 Turbo, and Gemini 3 Flash see far higher usage than flagship counterparts. Users vote with their feet — speed and cost often matter more than peak performance.",
      color: C.accent2
    },
    {
      title: "Anthropic Growth Has Stalled",
      body: "Despite two models in the top 10 (Sonnet + Opus 4.6), combined growth is flat. The duo totals ~2T tokens, but momentum has slowed amid rising competition.",
      color: C.accent4
    }
  ];

  trends.forEach((t, i) => {
    const x = 0.5 + i * 3.2;
    s.addShape(pres.shapes.RECTANGLE, {
      x: x, y: 1.0, w: 2.9, h: 3.6,
      fill: { color: C.cardBg },
      shadow: makeShadow(0.1)
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: x, y: 1.0, w: 2.9, h: 0.06,
      fill: { color: t.color }
    });
    s.addText(t.title, {
      x: x + 0.15, y: 1.2, w: 2.6, h: 0.7,
      fontSize: 16, fontFace: "Calibri", bold: true,
      color: C.navy, align: "left", valign: "top"
    });
    s.addText(t.body, {
      x: x + 0.15, y: 2.0, w: 2.6, h: 2.4,
      fontSize: 12, fontFace: "Calibri",
      color: C.slate, align: "left", valign: "top"
    });
  });

  // Bottom stat bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 9, h: 0.6,
    fill: { color: C.navy }
  });
  s.addText("Weekly token usage grew from ~2T to ~26T over the past year — a 13× expansion", {
    x: 0.5, y: 4.85, w: 9, h: 0.6,
    fontSize: 14, fontFace: "Calibri",
    color: C.white, align: "center", valign: "middle"
  });
}

// ===== SLIDE 5: Rising Stars =====
{
  const s = pres.addSlide();
  s.background = { color: C.bgLight };
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }
  });
  s.addText("This Week's Rising Stars: Fastest-Growing Models", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Calibri", bold: true,
    color: C.navy, align: "left", valign: "middle"
  });

  // Bar chart of fastest-growing models
  s.addChart(pres.charts.BAR, [{
    name: "WoW Growth",
    labels: ["MiniMax M2.7", "MiMo-V2-Pro", "Cline", "Codex", "Hermes Agent", "Ampere"],
    values: [253, 165, 128, 112, 92, 576]
  }], {
    x: 0.5, y: 1.0, w: 5.5, h: 4.0,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [C.accent3],
    chartArea: { fill: { color: C.cardBg }, roundedCorners: true },
    catAxisLabelColor: C.slate,
    valAxisLabelColor: C.lightSlate,
    valGridLine: { color: C.grid, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.slate,
    dataLabelFontSize: 11,
    showLegend: false,
    title: "Week-over-Week Growth (%)",
    titleFontSize: 12,
    titleColor: C.lightSlate
  });

  // Right-side analysis cards
  const cards = [
    { title: "MiniMax M2.7", growth: "+253%", desc: "Strongest growth this week. The M2 series is gaining rapid traction among developers." },
    { title: "MiMo-V2-Pro", growth: "+165%", desc: "Xiaomi's flagship continues explosive expansion, cementing its #1 position." },
    { title: "Cline", growth: "+128%", desc: "Autonomous coding agent surge reflects the booming AI developer tools market." }
  ];

  cards.forEach((c, i) => {
    const y = 1.0 + i * 1.35;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.3, y: y, w: 3.3, h: 1.15,
      fill: { color: C.cardBg },
      shadow: makeShadow(0.1)
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.3, y: y, w: 0.06, h: 1.15,
      fill: { color: C.accent3 }
    });
    s.addText(c.growth, {
      x: 6.5, y: y + 0.1, w: 1.0, h: 0.4,
      fontSize: 20, fontFace: "Calibri", bold: true,
      color: C.accent3, align: "left", valign: "middle"
    });
    s.addText(c.title, {
      x: 7.5, y: y + 0.1, w: 2.0, h: 0.4,
      fontSize: 14, fontFace: "Calibri", bold: true,
      color: C.navy, align: "left", valign: "middle"
    });
    s.addText(c.desc, {
      x: 6.5, y: y + 0.52, w: 3.0, h: 0.55,
      fontSize: 11, fontFace: "Calibri Light",
      color: C.lightSlate, align: "left", valign: "top"
    });
  });
}

// ===== SLIDE 6: App Ecosystem =====
{
  const s = pres.addSlide();
  s.background = { color: C.bgLight };
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }
  });
  s.addText("App Ecosystem: Who's Calling These Models", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Calibri", bold: true,
    color: C.navy, align: "left", valign: "middle"
  });

  // Top apps table (compact)
  const appRows = [
    [
      { text: "Rank", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "App", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "left" } },
      { text: "Daily Tokens", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "Category", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "left" } }
    ],
    ["1", "OpenClaw", "829B", "AI productivity assistant"],
    ["2", "Kilo Code", "271B", "VS Code AI coding assistant"],
    ["3", "Claude Code", "78B", "CLI coding tool"],
    ["4", "Cline", "69.1B", "Autonomous coding agent"],
    ["5", "Janitor AI", "29.2B", "Character roleplay chat"],
    ["6", "ISEKAI ZERO", "28.8B", "AI adventure game"],
    ["7", "Descript", "27B", "Video/podcast editor"],
    ["8", "Hermes Agent", "19.2B", "AI agent"],
    ["9", "Roo Code", "11.8B", "VS Code AI coding assistant"],
    ["10", "Scripty", "9.95B", "Newly launched tool"]
  ];

  const appTableData = appRows.map((row, ri) => {
    if (ri === 0) return row;
    return row.map((cell, ci) => {
      const base = { align: ci === 0 || ci === 2 ? "center" : "left", fontSize: 12, fontFace: "Calibri", color: C.slate };
      if (ri === 1 && ci === 1) return { text: cell, options: { ...base, bold: true, color: C.navy } };
      return { text: cell, options: base };
    });
  });

  s.addTable(appTableData, {
    x: 0.5, y: 1.0, w: 5.0, h: 4.2,
    colW: [0.7, 2.0, 1.2, 2.1],
    border: { pt: 0.5, color: C.grid },
    fill: { color: C.cardBg },
    valign: "middle"
  });

  // Right-side insight
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 1.0, w: 3.8, h: 2.0,
    fill: { color: C.navy }
  });
  s.addText("AI Coding Agents Dominate", {
    x: 5.95, y: 1.15, w: 3.5, h: 0.5,
    fontSize: 18, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", valign: "middle"
  });
  s.addText("The top 4 apps are all coding tools. This is the single largest LLM consumption scenario today.", {
    x: 5.95, y: 1.7, w: 3.5, h: 1.1,
    fontSize: 12, fontFace: "Calibri",
    color: C.ice, align: "left", valign: "top"
  });

  // OpenClaw callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 3.2, w: 3.8, h: 1.9,
    fill: { color: C.cardBg },
    shadow: makeShadow(0.1)
  });
  s.addText("829B", {
    x: 5.95, y: 3.35, w: 3.5, h: 0.7,
    fontSize: 36, fontFace: "Calibri", bold: true,
    color: C.accent, align: "left", valign: "middle"
  });
  s.addText("tokens/day consumed by OpenClaw — nearly 3× the #2 app", {
    x: 5.95, y: 4.05, w: 3.5, h: 0.9,
    fontSize: 12, fontFace: "Calibri Light",
    color: C.lightSlate, align: "left", valign: "top"
  });
}

// ===== SLIDE 7: Key Insights and Industry Implications =====
{
  const s = pres.addSlide();
  s.background = { color: C.navy };
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }
  });
  s.addText("Key Insights and Industry Implications", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", valign: "middle"
  });

  const takeaways = [
    {
      num: "01",
      title: "Chinese Models Hold Dominant Global Share",
      desc: "Combined Chinese provider share exceeds 54% on OpenRouter, an international platform. Cost-performance advantages are driving real-world adoption."
    },
    {
      num: "02",
      title: "AI Coding Agents = Largest Usage Category",
      desc: "5 of the top 10 apps are coding tools. The single biggest commercial value proposition for LLMs today is helping developers write code."
    },
    {
      num: "03",
      title: "No Outright Winner — Market Is Highly Fragmented",
      desc: "The top 10 models span 8 different providers. No single model or provider monopolizes usage, signaling fierce competition."
    },
    {
      num: "04",
      title: "Affordable & Fast Models Outpace Flagships",
      desc: "Flash/Turbo variants see far higher real-world usage than flagship models. Speed and cost often matter more than peak performance."
    }
  ];

  takeaways.forEach((t, i) => {
    const y = 1.0 + i * 1.1;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: y, w: 9, h: 0.95,
      fill: { color: "1A2A5E" }
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: y, w: 0.06, h: 0.95,
      fill: { color: C.accent }
    });
    s.addText(t.num, {
      x: 0.7, y: y, w: 0.5, h: 0.95,
      fontSize: 20, fontFace: "Calibri", bold: true,
      color: C.accent, align: "center", valign: "middle"
    });
    s.addText(t.title, {
      x: 1.3, y: y + 0.08, w: 8.0, h: 0.35,
      fontSize: 15, fontFace: "Calibri", bold: true,
      color: C.white, align: "left", valign: "middle"
    });
    s.addText(t.desc, {
      x: 1.3, y: y + 0.42, w: 8.0, h: 0.45,
      fontSize: 11, fontFace: "Calibri Light",
      color: C.ice, align: "left", valign: "top"
    });
  });
}

// Write file
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Saved /app/output/final_deck.pptx"))
  .catch(err => {
    console.error("Error:", err);
    process.exit(1);
  });

const pptxgen = require("pptxgenjs");

// Color palette: Midnight Executive with data-forward accent
const C = {
  navy: "1E2761",
  ice: "CADCFC",
  white: "FFFFFF",
  slate: "334155",
  lightSlate: "64748B",
  accent: "0EA5E9", // bright data blue
  accent2: "8B5CF6", // purple for variety
  accent3: "10B981", // emerald for growth
  accent4: "F59E0B", // amber for caution
  bgLight: "F8FAFC",
  cardBg: "FFFFFF",
  grid: "E2E8F0"
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "The 2025 LLM Usage Landscape: Real-World Data from OpenRouter";
pres.author = "Data Analysis Team";
pres.subject = "LLM Market Analysis";

// Helper: fresh shadow factory
const makeShadow = (opacity = 0.12) => ({
  type: "outer",
  blur: 6,
  offset: 2,
  angle: 135,
  color: "000000",
  opacity
});

// ===== SLIDE 1: Title =====
{
  const s = pres.addSlide();
  s.background = { color: C.navy };
  // Subtle top accent bar (inset from edges)
